import type {MarketAsset, MarketSnapshot} from '../models/market';
import {getMarketRecommendation} from './recommendation';

export const MARKET_DATA_SOURCE = {
  name: 'CoinGecko',
  url: 'https://www.coingecko.com/',
} as const;

export const MARKET_DISCLAIMER =
  'Информация носит справочный характер и не является индивидуальной инвестиционной рекомендацией. Криптоактивы волатильны, а прошлое движение цены не гарантирует будущий результат.';

export const MARKET_ASSET_IDS = [
  'bitcoin',
  'ethereum',
  'solana',
  'binancecoin',
  'ripple',
] as const;

const COINGECKO_MARKETS_ENDPOINT =
  'https://api.coingecko.com/api/v3/coins/markets';

export interface MarketFetchResponse {
  ok: boolean;
  status: number;
  json(): Promise<unknown>;
}

export type MarketFetch = (url: string) => Promise<MarketFetchResponse>;

interface CoinGeckoMarketRow {
  id: string;
  symbol: string;
  name: string;
  current_price: number;
  price_change_percentage_24h: number | null;
  last_updated: string | null;
}

export class MarketServiceError extends Error {
  readonly status: number | null;

  constructor(message: string, status: number | null = null) {
    super(message);
    this.name = 'MarketServiceError';
    this.status = status;
  }
}

export async function fetchMarketSnapshot(
  fetchImpl: MarketFetch = defaultMarketFetch,
): Promise<MarketSnapshot> {
  const url = buildMarketsUrl();
  let response: MarketFetchResponse;

  try {
    response = await fetchImpl(url);
  } catch (error) {
    throw new MarketServiceError(
      `Не удалось получить рыночные данные: ${toErrorMessage(error)}`,
    );
  }

  if (!response.ok) {
    throw new MarketServiceError(
      `Рыночный API вернул ошибку HTTP ${response.status}.`,
      response.status,
    );
  }

  let payload: unknown;
  try {
    payload = await response.json();
  } catch (error) {
    throw new MarketServiceError(
      `Не удалось прочитать ответ рыночного API: ${toErrorMessage(error)}`,
      response.status,
    );
  }

  const rows = parseMarketRows(payload);
  const assets = rows.map(toMarketAsset);
  const bitcoin = assets.find(asset => asset.id === 'bitcoin');

  if (!bitcoin) {
    throw new MarketServiceError('В ответе рыночного API отсутствует курс Bitcoin.');
  }

  return {
    bitcoinUsd: bitcoin.currentPriceUsd,
    assets,
    fetchedAt: new Date().toISOString(),
    source: MARKET_DATA_SOURCE,
    disclaimer: MARKET_DISCLAIMER,
  };
}

export function buildMarketsUrl(): string {
  const params = new URLSearchParams({
    vs_currency: 'usd',
    ids: MARKET_ASSET_IDS.join(','),
    order: 'market_cap_desc',
    sparkline: 'false',
    price_change_percentage: '24h',
  });

  return `${COINGECKO_MARKETS_ENDPOINT}?${params.toString()}`;
}

async function defaultMarketFetch(url: string): Promise<MarketFetchResponse> {
  return fetch(url);
}

function parseMarketRows(payload: unknown): CoinGeckoMarketRow[] {
  if (!Array.isArray(payload)) {
    throw new MarketServiceError('Рыночный API вернул данные в неожиданном формате.');
  }

  return payload.map((row, index) => {
    if (!isRecord(row)) {
      throw new MarketServiceError(`Некорректная запись актива с индексом ${index}.`);
    }

    const id = readString(row.id);
    const symbol = readString(row.symbol);
    const name = readString(row.name);
    const currentPrice = readFiniteNumber(row.current_price);
    const priceChange = readNullableFiniteNumber(row.price_change_percentage_24h);
    const lastUpdated = readNullableString(row.last_updated);

    if (!id || !symbol || !name || currentPrice === null) {
      throw new MarketServiceError(`Неполные данные актива с индексом ${index}.`);
    }

    return {
      id,
      symbol,
      name,
      current_price: currentPrice,
      price_change_percentage_24h: priceChange,
      last_updated: lastUpdated,
    };
  });
}

function toMarketAsset(row: CoinGeckoMarketRow): MarketAsset {
  return {
    id: row.id,
    symbol: row.symbol.toUpperCase(),
    name: row.name,
    currentPriceUsd: row.current_price,
    priceChange24hPercent: row.price_change_percentage_24h,
    lastUpdated: row.last_updated,
    recommendation: getMarketRecommendation(row.price_change_percentage_24h),
  };
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null;
}

function readString(value: unknown): string | null {
  return typeof value === 'string' && value.length > 0 ? value : null;
}

function readNullableString(value: unknown): string | null {
  return value === null || value === undefined ? null : readString(value);
}

function readFiniteNumber(value: unknown): number | null {
  return typeof value === 'number' && Number.isFinite(value) ? value : null;
}

function readNullableFiniteNumber(value: unknown): number | null {
  return value === null || value === undefined ? null : readFiniteNumber(value);
}

function toErrorMessage(error: unknown): string {
  return error instanceof Error ? error.message : 'неизвестная ошибка';
}
