import type {MarketRecommendation} from '../models/market';

const HIGH_RISK_ABSOLUTE_CHANGE_PERCENT = 7;
const WATCH_POSITIVE_CHANGE_PERCENT = 2;

/**
 * Produces an informational label from 24h price movement only.
 * It intentionally does not attempt to predict future returns or tell a user what to buy.
 */
export function getMarketRecommendation(
  priceChange24hPercent: number | null,
): MarketRecommendation {
  if (priceChange24hPercent === null || !Number.isFinite(priceChange24hPercent)) {
    return {
      kind: 'neutral',
      label: 'Нейтрально',
      reason: 'Недостаточно данных о движении цены за последние 24 часа.',
    };
  }

  const absoluteChange = Math.abs(priceChange24hPercent);

  if (absoluteChange >= HIGH_RISK_ABSOLUTE_CHANGE_PERCENT) {
    return {
      kind: 'high_risk',
      label: 'Повышенный риск',
      reason: `Цена изменилась на ${formatPercent(priceChange24hPercent)} за 24 часа; высокая краткосрочная волатильность требует осторожности.`,
    };
  }

  if (priceChange24hPercent >= WATCH_POSITIVE_CHANGE_PERCENT) {
    return {
      kind: 'watch',
      label: 'Интересно наблюдать',
      reason: `Цена выросла на ${formatPercent(priceChange24hPercent)} за 24 часа; это сигнал движения, а не прогноз дальнейшего роста.`,
    };
  }

  return {
    kind: 'neutral',
    label: 'Нейтрально',
    reason: `Изменение за 24 часа (${formatPercent(priceChange24hPercent)}) не превышает заданные пороги наблюдения и риска.`,
  };
}

function formatPercent(value: number): string {
  const sign = value > 0 ? '+' : '';
  return `${sign}${value.toFixed(2)}%`;
}
