import React from 'react';
import {Text} from 'react-native';
import ReactTestRenderer from 'react-test-renderer';
import {HomeScreen} from '../src/screens';

async function renderScreen(props: React.ComponentProps<typeof HomeScreen> = {}) {
  let renderer: ReactTestRenderer.ReactTestRenderer;

  await ReactTestRenderer.act(() => {
    renderer = ReactTestRenderer.create(<HomeScreen {...props} />);
  });

  return renderer!;
}

function renderedText(renderer: ReactTestRenderer.ReactTestRenderer) {
  return renderer.root
    .findAllByType(Text)
    .map(node => React.Children.toArray(node.props.children).join(''))
    .join(' ');
}

describe('HomeScreen', () => {
  it('shows the Bitcoin quote and recommendation cards', async () => {
    const renderer = await renderScreen();
    const output = renderedText(renderer);

    expect(output).toContain('Bitcoin сейчас');
    expect(output).toContain('$67,842.52');
    expect(output).toContain('+2.84% за 24 ч');
    expect(output).toContain('Какие активы посмотреть');
    expect(output).toContain('Ethereum');
    expect(output).toContain('Solana');
    expect(output).toContain('Chainlink');
  });

  it.each([
    ['loading', 'Загружаем рынок'],
    ['error', 'Не удалось обновить данные'],
    ['empty', 'Данных пока нет'],
  ] as const)('renders the %s state', async (state, expectedText) => {
    const renderer = await renderScreen({state});
    expect(renderedText(renderer)).toContain(expectedText);
  });

  it('runs refresh from the refresh button', async () => {
    const onRefresh = jest.fn();
    const renderer = await renderScreen({onRefresh});
    const refreshButton = renderer.root
      .findAll(node => node.props.accessibilityLabel === 'Обновить котировки')
      .find(node => typeof node.props.onPress === 'function');

    expect(refreshButton).toBeDefined();

    await ReactTestRenderer.act(async () => {
      await refreshButton?.props.onPress();
    });

    expect(onRefresh).toHaveBeenCalledTimes(1);
  });
});
